#!/bin/bash
set -e
R=android/app/src/main/res
rm -rf "$R/mipmap-anydpi-v26"
for d in mdpi hdpi xhdpi xxhdpi xxxhdpi; do
  mkdir -p "$R/mipmap-$d"
  cp build/icon-192.png "$R/mipmap-$d/ic_launcher.png"
  cp build/icon-192.png "$R/mipmap-$d/ic_launcher_round.png"
  cp build/icon-192.png "$R/mipmap-$d/ic_launcher_foreground.png"
done
M=android/app/src/main/AndroidManifest.xml
grep -q POST_NOTIFICATIONS "$M" || sed -i 's#</manifest>#    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />\n</manifest>#' "$M"
for P in SCHEDULE_EXACT_ALARM USE_EXACT_ALARM RECEIVE_BOOT_COMPLETED VIBRATE WAKE_LOCK; do
  grep -q "android.permission.$P\"" "$M" || sed -i "s#</manifest>#    <uses-permission android:name=\"android.permission.$P\" />\n</manifest>#" "$M"
done
mkdir -p "$R/drawable-mdpi"
echo "" | base64 -d > "$R/drawable-mdpi/ic_stat_turqtrack.png"
mkdir -p "$R/drawable-hdpi"
echo "" | base64 -d > "$R/drawable-hdpi/ic_stat_turqtrack.png"
mkdir -p "$R/drawable-xhdpi"
echo "" | base64 -d > "$R/drawable-xhdpi/ic_stat_turqtrack.png"
mkdir -p "$R/drawable-xxhdpi"
echo "" | base64 -d > "$R/drawable-xxhdpi/ic_stat_turqtrack.png"
mkdir -p "$R/drawable-xxxhdpi"
echo "" | base64 -d > "$R/drawable-xxxhdpi/ic_stat_turqtrack.png"
mkdir -p "$R/drawable-xxhdpi"
echo "" | base64 -d > "$R/drawable-xxhdpi/tq_large.png"
